steps.script:
var phase = PhaseManager.get_current_phase_instance()
var stompa = GameState.get_unit("U_STOMPA_A")
return phase._position_overlaps_other_models("U_STOMPA_A", "m1", Vector2(775, 900), stompa["models"][0])

# Inject a wall segment straight across the Stompa so the endpoint check has
# something real to reject, then read the check on both paths.
TerrainManager.terrain_features.append({"id": "scenario_test_wall", "type": "ruins", "walls": [{"start": Vector2(400, 900), "end": Vector2(800, 900)}], "polygon": PackedVector2Array()})
var stompa = GameState.get_unit("U_STOMPA_A")
var m = stompa["models"][0].duplicate(true)
m["position"] = Vector2(600, 900)
return Measurement.model_overlaps_any_wall(m, stompa.get("meta", {}).get("keywords", []))

var phase = PhaseManager.get_current_phase_instance()
var stompa = GameState.get_unit("U_STOMPA_A")
return phase._position_overlaps_other_models("U_STOMPA_A", "m1", Vector2(775, 900), stompa["models"][0])

# Same injected wall, override now ON: the VEHICLE is let through, while a
# non-VEHICLE keyword list is still rejected by the very same wall.
var stompa = GameState.get_unit("U_STOMPA_A")
var m = stompa["models"][0].duplicate(true)
m["position"] = Vector2(600, 900)
var vehicle_blocked = Measurement.model_overlaps_any_wall(m, stompa.get("meta", {}).get("keywords", []))
var other_blocked = Measurement.model_overlaps_any_wall(m, ["ADEPTUS_CUSTODES"])
return "vehicle=%s other=%s" % [str(vehicle_blocked), str(other_blocked)]

var kept = []
for t in TerrainManager.terrain_features:
	if str(t.get("id", "")) != "scenario_test_wall":
		kept.append(t)
TerrainManager.terrain_features = kept
return TerrainManager.terrain_features.size()

var phase = PhaseManager.get_current_phase_instance()
var guard = GameState.get_unit("U_CUSTODIAN_GUARD_B")
return phase._position_overlaps_other_models("U_CUSTODIAN_GUARD_B", "m1", Vector2(762, 985), guard["models"][0])

SettingsService.set_disable_vehicle_collision(false)
var phase = PhaseManager.get_current_phase_instance()
var stompa = GameState.get_unit("U_STOMPA_A")
return phase._position_overlaps_other_models("U_STOMPA_A", "m1", Vector2(775, 900), stompa["models"][0])
